#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_delete_id_not_found(void) {
    // Setup: create a non-empty list where the target ID is not present
    node *root = NULL;
    // Insert some nodes with IDs 1, 2, 3
    insert(&root, 1, 0, 5, 1);
    insert(&root, 2, 1, 4, 2);
    insert(&root, 3, 2, 3, 3);
    // The list now has nodes with IDs 1, 2, 3
    // We will try to delete ID 99 which does not exist

    // Record initial state: count nodes
    int initial_count = l_length(&root);
    TEST_ASSERT_EQUAL_INT(3, initial_count);

    // Test: call delete with ID that does not exist
    delete(&root, 99);

    // Assertions:
    // 1. List should still have 3 nodes
    int final_count = l_length(&root);
    TEST_ASSERT_EQUAL_INT(3, final_count);
    // 2. All original nodes should still be present
    // We can traverse and check IDs
    node *ptr = root;
    int found_ids[3] = {0};
    while (ptr != NULL) {
        if (ptr->ID == 1) found_ids[0] = 1;
        if (ptr->ID == 2) found_ids[1] = 1;
        if (ptr->ID == 3) found_ids[2] = 1;
        ptr = ptr->next;
    }
    TEST_ASSERT_EQUAL_INT(1, found_ids[0]);
    TEST_ASSERT_EQUAL_INT(1, found_ids[1]);
    TEST_ASSERT_EQUAL_INT(1, found_ids[2]);

    // Cleanup
    helper_cleanup_process_queue(&root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_delete_id_not_found);
    return UNITY_END();
}

